// Validate, dedupe, upsert lead, insert touch-1 send row. Touch 1 is transactional artifact
// delivery, sent immediately; touches 2-4 queue at L1 via the Nurture Scheduler.
const FRAME = {"1":{"subject":"Your {artifact_name} is inside","body":"Here is your {artifact_name}: https://ctrl.mindmake.co/kit?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email\n\nNo signup wall, it is just yours.\n\nOne thing worth doing while you have it open: CTRL can build a portable context file of you in about 2 minutes. Paste it into ChatGPT or Claude and the next answer you get is about you, your company, your priorities. Not generic advice.\n\nThat part is free and takes less time than reading this email twice.\n\nBuild your context file: https://ctrl.mindmake.co?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"2":{"subject":"You re-explain yourself to AI every day","body":"Count how many times you told an AI tool who you are this week. Your role, your company, what you are working on. Every conversation starts from zero, so every answer stays generic. That is the zero-context tax, and leaders pay it daily.\n\nCTRL ends it. Two minutes of talking builds your Memory Web. One click exports it to any AI tool you already use.\n\nIf you have not built yours yet, it is free: https://ctrl.mindmake.co?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"3":{"subject":"What your context file is not telling you","body":"The free Memory Web tells your AI tools who you are. The Full Diagnostic tells you what you are not seeing: the tensions in how you are operating, the risks you are discounting, and the scenarios worth pressure-testing before they arrive.\n\nIt runs on the context you already built, so it is specific to your situation, not a template. One-time, $49, yours to keep.\n\nRun your Full Diagnostic: https://ctrl.mindmake.co?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"},"4":{"subject":"Last note from us","body":"This is the last email in this series, so the short version:\n\nYou built your context file. The Full Diagnostic is the deep read on it: tensions, risks, scenarios, the complete thinking tools. $49 once. If the free version was useful, this is the part leaders tell us was worth paying for.\n\nEither way, we stop emailing you after this.\n\nRun the Diagnostic: https://ctrl.mindmake.co?utm_campaign=mm_ctrl_nurture_v1&utm_source=nurture&utm_medium=email"}};
const FOOTER = "\n\n---\nCTRL by Mindmake. You received this because you requested an artifact at ctrl.mindmake.co.\nUnsubscribe: https://krishraja10101.app.n8n.cloud/webhook/ctrl-unsub?e={email}";
const SB = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SBH = { apikey: '{{SUPABASE_SERVICE_ROLE_KEY}}', Authorization: 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}', 'Content-Type': 'application/json' };
const b = $input.first().json.body || {};
const email = String(b.email || '').trim().toLowerCase();
const honeypot = String(b.website || '');
const valid = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) && honeypot === '';
if (!valid) return [{ json: { skipped: true, reason: honeypot ? 'honeypot' : 'invalid_email', email } }];

const artifact = String(b.artifact_name || 'CTRL starter kit').slice(0, 120);
const utm = { utm_source: b.utm_source || 'direct', utm_medium: b.utm_medium || 'organic', utm_campaign: b.utm_campaign || 'mm_ctrl_capture', utm_content: b.utm_content || null, utm_term: b.utm_term || null };

function q(params){ const p=[]; for (const k of Object.keys(params)) p.push(encodeURIComponent(k)+'='+encodeURIComponent(params[k])); return p.join('&'); }

// find or create the lead
let lead = null;
const found = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/leads?' + q({ select: 'id,churned_at', email: 'eq.' + email, primary_venture: 'eq.mm_ctrl', limit: '1' }), headers: SBH, json: true });
if (Array.isArray(found) && found.length > 0) lead = found[0];
if (lead && lead.churned_at) return [{ json: { skipped: true, reason: 'suppressed', email } }];
if (!lead) {
  const ins = await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/leads', headers: { ...SBH, Prefer: 'return=representation' }, body: [{ email, full_name: b.full_name || null, source_type: 'capture', source_ref: utm.utm_campaign, source_url: b.page_url || null, primary_venture: 'mm_ctrl', status: 'new', owner: 'system', assignee_agent: 'cleo', raw_extraction: { capture: true, artifact, ...utm } }], json: true });
  lead = ins[0];
}

// touch-1 send row; the unique constraint is the idempotency backstop
const subject = FRAME[1].subject.replace('{artifact_name}', artifact);
const bodyTxt = FRAME[1].body.replace('{artifact_name}', artifact) + FOOTER.replace('{email}', encodeURIComponent(email));
let sendRow = null;
try {
  const s = await this.helpers.httpRequest({ method: 'POST', url: SB + '/rest/v1/acquisition_sends', headers: { ...SBH, Prefer: 'return=representation' }, body: [{ lead_id: lead.id, lane: 'mm_ctrl', touch_number: 1, rendered_subject: subject, rendered_body: bodyTxt, status: 'approved' }], json: true });
  sendRow = s[0];
} catch (e) {
  return [{ json: { skipped: true, reason: 'duplicate_capture', email, lead_id: lead.id } }];
}
return [{ json: { skipped: false, email, lead_id: lead.id, send_id: sendRow.id, subject, bodyTxt, artifact } }];
